"use client";

import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import {
  primaryFace,
  primaryFaceHover,
  focusRing,
  pressScale,
  quietChip,
  raisedSurface,
} from "./_shared";

/**
 * Paddock IconButton: a single glyph on the same fills as the Button.
 *
 * The default is the white surface with a 1px cool border; `primary` is the
 * solid teal fill and `ghost` is the bare glyph, as used for the "more" dots
 * on a row. Square corners follow the
 * radius scale, so a bigger button keeps a softer corner.
 */
const iconButtonVariants = cva(
  [
    "relative inline-flex shrink-0 select-none items-center justify-center",
    pressScale,
    focusRing,
    "disabled:pointer-events-none disabled:opacity-50",
    "data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
    "[&_svg]:pointer-events-none [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        default: raisedSurface,
        primary: cn(primaryFace, primaryFaceHover),
        secondary: quietChip,
        ghost:
          "bg-transparent text-muted-foreground hover:bg-accent hover:text-foreground",
        destructive:
          "bg-destructive text-destructive-foreground shadow-(--card-ring) hover:bg-destructive/90",
        outline:
          "border border-input bg-transparent text-foreground hover:bg-accent",
      },
      size: {
        xs: "size-6 rounded-sm [&_svg]:size-3.5",
        sm: "size-8 rounded-sm [&_svg]:size-4",
        default: "size-10 rounded-md [&_svg]:size-4",
        lg: "size-11 rounded-lg [&_svg]:size-5",
        xl: "size-12 rounded-xl [&_svg]:size-5",
      },
      corners: {
        square: "",
        circle: "rounded-full",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
      corners: "circle",
    },
  },
);

/** Props for the IconButton. Give it an `aria-label`, since the glyph carries no text. */
export interface IconButtonProps
  extends
    Omit<ButtonPrimitive.Props, "className">,
    VariantProps<typeof iconButtonVariants> {
  className?: string;
}

const IconButton = React.forwardRef<HTMLButtonElement, IconButtonProps>(
  ({ className, variant, size, corners, ...props }, ref) => (
    <ButtonPrimitive
      ref={ref}
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant, size, corners, className }))}
      {...props}
    />
  ),
);
IconButton.displayName = "IconButton";

export { IconButton, iconButtonVariants };
